function t(value){return language==='en'?(translations[value]||value):value;}
function applyPreferences(){
 document.documentElement.lang=language;
 document.documentElement.dataset.theme=blackTheme?'black':'purple';
 document.querySelectorAll('[data-i18n]').forEach(n=>{n.textContent=t(n.dataset.i18n);});
 document.querySelectorAll('[data-i18n-placeholder]').forEach(n=>n.placeholder=t(n.dataset.i18nPlaceholder));
 document.querySelectorAll('[data-i18n-label]').forEach(n=>n.setAttribute('aria-label',t(n.dataset.i18nLabel)));
 $('language').value=language;
 $('language').setAttribute('aria-label',language==='es'?'Idioma':'Language');
 $('theme').textContent=blackTheme?(language==='es'?'◐ Morado':'◐ Purple'):(language==='es'?'◐ Negro':'◐ Black');
 $('theme').setAttribute('aria-pressed',String(blackTheme));
 document.querySelector('meta[name="theme-color"]').content=blackTheme?'#000000':'#100b1c';
 if(document.documentElement.dataset.tvConnected==='true')$('castTools').textContent=t('TV conectada');
}

const BASE='https://iwvhigqxsvvgyzdygiqa.supabase.co',KEY='sb_publishable_TdzEQXtDadVMKhSLVe0ihw_EAQ4iNsd';
const $=id=>document.getElementById(id),el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
let session=null;try{session=JSON.parse(sessionStorage.getItem('brunio-session'));}catch{}let profiles=[],favorites=new Set(),items=[],view='explore',filter='all',page=1,hasMore=false,generation=0,refreshing=null,loading=false;
const cache=new Map();let toastTimer;
function toast(msg){$('toast').textContent=msg;$('toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').style.display='none',3500);}
function saveSession(s){session=s;if(s)sessionStorage.setItem('brunio-session',JSON.stringify(s));else sessionStorage.removeItem('brunio-session');}
function logout(){generation++;saveSession(null);cache.clear();favorites.clear();$('app').hidden=true;$('login').hidden=false;$('account').hidden=true;$('detail').close();$('friendsPanel').hidden=true;$('calendarPanel').hidden=true;$('eventDialog').close();}
async function refreshToken(){if(!refreshing)refreshing=(async()=>{const old=session;if(!old)throw Error(t('Inicia sesión'));const r=await fetch(BASE+'/auth/v1/token?grant_type=refresh_token',{method:'POST',headers:{apikey:KEY,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:old.refresh_token})});if(!r.ok){if(r.status===400||r.status===401){logout();throw Error(t('Tu sesión venció. Entra de nuevo.'));}throw Error(t('No se pudo renovar la sesión. Reintenta.'));}const s=await r.json();if(session===old)saveSession({...s,expires_at:Date.now()+s.expires_in*1000});})();try{await refreshing;}finally{refreshing=null;}}
async function api(path,method='GET',body,retry=true){if(!session)throw Error(t('Inicia sesión'));if(session.expires_at<Date.now()+30000)await refreshToken();const owner=session.user.id;const r=await fetch(BASE+path,{method,headers:{apikey:KEY,Authorization:'Bearer '+session.access_token,'Content-Type':'application/json',...(path.startsWith('/rest/v1/miflix_recommendations?on_conflict=')?{Prefer:'resolution=merge-duplicates,return=minimal'}:{})},...(body!==undefined?{body:JSON.stringify(body)}:{})});if(r.status===401&&retry){await refreshToken();return api(path,method,body,false);}if(session?.user.id!==owner)throw Error(t('La cuenta cambió'));let data;try{data=await r.json();}catch{data=null;}if(!r.ok)throw Error(r.status===404?t('Falta configurar la función o tabla en Supabase.'):data?.error||data?.message||t('No se pudo completar la solicitud.'));return data;}
async function catalog(body){body={...body,language};const key=JSON.stringify(body),old=cache.get(key);if(old&&Date.now()-old.at<300000)return old.data;const data=await api('/functions/v1/brunio-catalog','POST',body);if(cache.size>100)cache.clear();cache.set(key,{at:Date.now(),data});return data;}
const selected=()=>$('profile').value;
async function readFavorites(){const owner=session?.user.id,profile=selected();const rows=await api('/rest/v1/miflix_user_state?user_id=eq.'+session.user.id+'&profile_id=eq.'+encodeURIComponent(selected())+'&select=state');if(session?.user.id!==owner||selected()!==profile)throw Error(t('La cuenta cambió'));recentProgress=rows[0]?.state?.progress||{};return new Set((rows[0]?.state?.favorites||[]).filter(x=>/^tmdb:(movie|series):\d+$/.test(x)));}
function updateCount(){$('count').textContent=favorites.size;}
async function init(){const ticket=++generation;$('login').hidden=true;$('app').hidden=false;$('account').hidden=false;$('status').textContent=t('Cargando tus perfiles…');try{const rows=await api('/rest/v1/miflix_user_state?user_id=eq.'+session.user.id+'&select=profile_id,profiles:state->profiles');if(ticket!==generation)return;profiles=rows.find(x=>x.profile_id==='__account__')?.profiles||[];if(!profiles.length)profiles=rows.filter(x=>x.profile_id!=='__account__').map(x=>({id:x.profile_id,name:t('Mi perfil')}));if(!profiles.length)throw Error(t('Crea primero un perfil en BruniO TV.'));$('profile').replaceChildren(...profiles.map(p=>{const n=el('option',p.name);n.value=p.id;return n;}));await loadConfig();await changeProfile();}catch(e){$('status').textContent=e.message;}}
async function changeProfile(){const ticket=++generation;try{const next=await readFavorites();if(ticket!==generation)return;favorites=next;updateCount();$('profileName').textContent=t('EL ESPACIO DE ')+(profiles.find(p=>p.id===selected())?.name||t('TU PERFIL')).toUpperCase();if(view==='calendar')await loadCalendar();else if(view==='friends')await loadFriends();else await load(true);await openSharedTitle();}catch(e){if(ticket===generation)$('status').textContent=e.message;}}
async function toggle(item,button){if(button.disabled)return;button.disabled=true;const profile=selected(),uid=session?.user.id,remove=favorites.has(item.cloudId);try{const data=await api('/rest/v1/rpc/brunio_sync_profile','POST',{p_profile:profile,p_adds:remove?[]:[item.cloudId],p_removes:remove?[item.cloudId]:[],p_progress:null});if(selected()!==profile||session?.user.id!==uid)return;favorites=new Set(data.favorites||[]);updateCount();render();toast(remove?t('Quitado de Mi lista'):t('Guardado para tu próxima noche de cine'));if($('detail').open)showDetail(item);}catch(e){toast(e.message);}finally{button.disabled=false;}}
function safeImage(url){try{const u=new URL(url);return u.protocol==='https:'&&u.hostname==='image.tmdb.org'?u.href:null;}catch{return null;}}
function card(item){const c=el('article',undefined,'card'),poster=el('button',undefined,'poster');poster.setAttribute('aria-label',t('Detalles de ')+item.title);const src=safeImage(item.poster);if(src){const img=el('img');img.src=src;img.alt='';img.loading='lazy';poster.append(img);}else poster.append(el('span','◈','placeholder'));poster.onclick=()=>openDetail(item);const saved=favorites.has(item.cloudId),b=el('button',saved?'✓':'+','save'+(saved?' saved':''));b.setAttribute('aria-label',(saved?t('Quitar '):t('Guardar '))+item.title);b.onclick=()=>toggle(item,b);c.append(poster,b,el('h3',item.title),el('p',[item.year,item.type==='series'?t('Serie'):t('Película'),item.rating?'★ '+Number(item.rating).toFixed(1):''].filter(Boolean).join(' · ')));return c;}
function render(){const visible=items.filter(x=>(filter==='all'||x.type===filter)&&(view!=='mylist'||((!$('genre').value||x.genres?.includes(Number($('genre').value)))&&(!$('year').value||x.year===$('year').value))));if(view==='mylist')visible.sort((a,b)=>$('sort').value==='date.desc'?(b.date||'').localeCompare(a.date||''):$('sort').value==='vote_average.desc'?(b.rating||0)-(a.rating||0):0);$('grid').replaceChildren(...visible.map(card));if(!loading&&!visible.length)$('status').textContent=view==='mylist'?t('Tu lista está vacía con este filtro. Guarda algo en Explorar.'):t('Sin resultados. Prueba otros filtros o pulsa Ver más.');$('more').hidden=!hasMore;}
async function openDetail(item){showDetail(item);const ticket=detailRevision,lang=language;try{const data=await catalog({action:'titles',ids:[item.cloudId]});if(ticket===detailRevision&&lang===language&&$('detail').open&&data.items[0])showDetail(data.items[0]);}catch(e){if(ticket===detailRevision)toast(e.message);}}
let currentDetail=null;
function showDetail(item){
 if(currentDetail?.cloudId!==item.cloudId){$('castSeason').value='1';$('castEpisode').value='1';}
 currentDetail=item;detailRevision++;const root=$('detailBody');root.replaceChildren();
 const hero=el('div',undefined,'detail-hero'),src=safeImage(item.backdrop||item.poster);
 if(src){const img=el('img');img.src=src;img.alt='';hero.append(img);}
 const heading=el('div',undefined,'detail-hero-title');heading.append(el('p',t(item.type==='series'?'SERIE':'PELÍCULA'),'eyebrow'),el('h2',item.title));hero.append(heading);root.append(hero);
 const info=el('div',undefined,'detail-info');info.append(el('p',[item.date?t('Estreno: ')+item.date:item.year,item.rating?'★ '+Number(item.rating).toFixed(1):'',item.runtime?item.runtime+' min':''].filter(Boolean).join(' · '),'detail-meta'));
 const genres=(item.genres||[]).map(g=>(catalogConfig?.genres?.[item.type]||[]).find(x=>x.id===g)?.name).filter(Boolean);if(genres.length)info.append(el('p',genres.join(' · '),'detail-meta'));
 info.append(el('p',item.overview||t('No hay descripción disponible.'),'detail-synopsis'));
 const actions=el('div',undefined,'detail-actions');
 const play=el('button',t('Reproducir en TV'),'primary');play.onclick=()=>{if(!castToken){openCast(item);return;}castItem=item;play.disabled=true;castSend('play').finally(()=>play.disabled=false);};actions.append(play);
 const list=el('button',favorites.has(item.cloudId)?t('✓ En Mi lista · Quitar'):t('+ Agregar a Mi lista'),'quiet');list.onclick=()=>toggle(item,list);actions.append(list);
 for(const [label,handler] of [['Compartir',()=>shareTitle(item)],['Recomendar a amigos',()=>recommendTitle(item)],['Crear evento',()=>openEvent(item)],['Enviar a TV',()=>openCast(item)],['Download',()=>openDownloads(item)]]){const b=el('button',t(label),'quiet');b.onclick=handler;actions.append(b);}
 if(item.type==='series'){
  const fields=el('div',undefined,'event-fields');for(const [id,label] of [['castSeason','Temporada'],['castEpisode','Episodio']]){const l=el('label',t(label)),n=el('input');n.type='number';n.min='1';n.max='10000';n.value=$(id).value||'1';n.oninput=()=>{$(id).value=n.value;};l.append(n);fields.append(l);}info.append(fields);
 }
 info.append(actions);root.append(info);if(!$('detail').open)$('detail').showModal();
}
async function titleBatch(ids){const items=[];for(let i=0;i<ids.length;i+=20){const data=await catalog({action:'titles',ids:ids.slice(i,i+20)});items.push(...data.items);}return {items};}
function shortTitleLink(item){return 'https://miflix-tv-native-web.vercel.app/#'+(item.type==='series'?'s':'m')+Number(item.id||item.cloudId.split(':')[2]).toString(36);}
async function shareTitle(item){const url=shortTitleLink(item);try{if(navigator.share){await navigator.share({title:item.title,url});return;}if(navigator.clipboard){await navigator.clipboard.writeText(url);toast(t('Enlace copiado'));return;}throw Error('clipboard');}catch(e){if(e.name==='AbortError')return;const input=el('input');input.value=url;input.readOnly=true;const label=el('label',t('Copiar este enlace:'));label.append(input);$('detailBody').append(label);input.focus();input.select();}}
async function openSharedTitle(){if(!pendingShared||!session||!selected())return;const id=pendingShared;pendingShared=null;try{const data=await catalog({action:'titles',ids:[id]});if(data.items[0])showDetail(data.items[0]);}catch(e){pendingShared=id;toast(e.message);}}
