function buildEventPayload(target,title,date,season,episode,guests,owner,now=Date.now()){if(!target)throw Error(t('Selecciona una película o serie.'));if(!title.trim()||title.trim().length>160)throw Error(t('Escribe un título de hasta 160 caracteres.'));const starts=new Date(date);if(!Number.isFinite(starts.getTime())||starts.getTime()<=now)throw Error(t('Elige una fecha futura.'));if(target.type==='series'&&(!Number.isInteger(season)||!Number.isInteger(episode)||season<1||episode<1))throw Error(t('Temporada y episodio deben ser números positivos.'));if(guests.length>20)throw Error(t('Selecciona hasta 20 amigos.'));return {owner_id:owner,title:title.trim(),kind:target.type,starts_at:starts.toISOString(),cloud_id:target.cloudId,season:target.type==='series'?season:0,episode:target.type==='series'?episode:0,guests};}
