// Local companion control. No Supabase commands, polling, URLs or playback in the browser.
let castItem=null,castToken='',castEndpoint='',castBusy=false;
function validCastAddress(value){
 let u;try{u=new URL(value.trim().startsWith('http://')?value.trim():'http://'+value.trim());}catch{throw Error(t('Usa la dirección Wi-Fi privada que muestra tu TV.'));}
 const ip=u.hostname.split('.').map(Number),privateIP=ip.length===4&&ip.every(x=>Number.isInteger(x)&&x>=0&&x<=255)&&(ip[0]===10||ip[0]===192&&ip[1]===168||ip[0]===172&&ip[1]>=16&&ip[1]<=31);
 if(u.protocol!=='http:'||!privateIP||u.port!=='8765'||u.username||u.password||u.pathname!=='/'||u.search||u.hash)throw Error(t('Usa la dirección Wi-Fi privada que muestra tu TV.'));return u.origin;
}
function castRender(){const connected=!!castToken;document.documentElement.dataset.tvConnected=String(connected);$('castForm').hidden=true;$('castLocal').hidden=true;$('castTools').textContent=connected?t('TV conectada'):t('Enviar a TV');$('castActions').hidden=!connected;$('castConnect').disabled=castBusy;$('castDetails').disabled=castBusy||!castItem;$('castPlay').disabled=castBusy||!castItem;$('castTitle').textContent=castItem?.title||t('Selecciona primero una película o serie.');}
function openCast(item=null){castItem=item;if(tvBridge){$('castAddress').value=castEndpoint;}else try{$('castAddress').value=localStorage.getItem('brunio-tv-address')||'';}catch{}$('castStatus').textContent=castToken?'':(language==='en'?'On your TV: Profile → Connect phone / PC. Scan the QR or open the complete link to connect automatically.':'En tu TV: Perfil → Connect phone / PC. Escanea el QR o abre el enlace completo para conectar automáticamente.');castRender();if(!$('castDialog').open)$('castDialog').showModal();}
async function castPost(path,data,authorized=false){
 if(tvBridge && authorized)return bridgeSend(data);
 const endpoint=validCastAddress($('castAddress').value);if(authorized&&endpoint!==castEndpoint)throw Error(t('Conexión caducada. Genera otro código en tu TV.'));
 const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),6500);
 try{const r=await fetch(endpoint+path,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded',...(authorized?{Authorization:'Bearer '+castToken}:{})},body:new URLSearchParams(data),signal:controller.signal,targetAddressSpace:'local'});
 if(r.status===401){castToken='';throw Error(t('Conexión caducada. Genera otro código en tu TV.'));}if(!r.ok)throw Error(t('Conexión no disponible. Verifica Wi-Fi y código; también puedes abrir el control local.'));return await r.json();}
 finally{clearTimeout(timeout);}
}
$('castTools').onclick=()=>openCast();$('castClose').onclick=()=>$('castDialog').close();
$('castAddress').oninput=()=>{castToken='';castRender();};
$('castForm').onsubmit=async e=>{e.preventDefault();if(castBusy)return;if(!/^[0-9]{6}$/.test($('castCode').value)){$('castCode').focus();return;}castBusy=true;castRender();try{const data=await castPost('/connect',{code:$('castCode').value});castEndpoint=validCastAddress($('castAddress').value);castToken=data.token;try{localStorage.setItem('brunio-tv-address',castEndpoint);}catch{}$('castStatus').textContent=t('Conectado a tu TV.');}catch(e){$('castStatus').textContent=e.message.startsWith('Failed')||e.name==='AbortError'?t('Conexión no disponible. Verifica Wi-Fi y código; también puedes abrir el control local.'):e.message;}finally{castBusy=false;castRender();}};
async function castSend(action){if(castBusy||!castItem)return;if(!$('castSeason').reportValidity()||!$('castEpisode').reportValidity())return;castBusy=true;castRender();try{await castPost('/send',{cloud:castItem.cloudId,action,season:$('castSeason').value,episode:$('castEpisode').value,request:Date.now().toString(36)+'-'+Math.random().toString(36).slice(2)},true);$('castStatus').textContent=t('Enviado. Revisa tu TV.');toast(t('Enviado. Revisa tu TV.'));setTimeout(pollNowPlaying,1500);}catch(e){$('castStatus').textContent=e.name==='TypeError'||e.name==='AbortError'?t('Conexión no disponible. Verifica Wi-Fi y código; también puedes abrir el control local.'):e.message;toast($('castStatus').textContent);}finally{castBusy=false;castRender();}}
$('castDetails').onclick=()=>castSend('details');$('castPlay').onclick=()=>castSend('play');$('castForget').onclick=()=>{if(tvBridge)window.parent.postMessage({brunio:'tv-client',action:'disconnect'},castEndpoint);castToken='';castEndpoint='';$('castCode').value='';$('nowPlaying').hidden=true;castRender();};
$('castLocal').onclick=()=>{try{const u=new URL(validCastAddress($('castAddress').value));const hash=new URLSearchParams();if(castItem){hash.set('cloud',castItem.cloudId);hash.set('title',castItem.title);}if(/^[0-9]{6}$/.test($('castCode').value))hash.set('code',$('castCode').value);u.hash=hash.toString();window.open(u.href,'_blank','noopener,noreferrer');}catch(e){$('castStatus').textContent=e.message;}};

// The TV hosts the parent page; the catalog stays on Vercel. Local requests are
// made by the same-origin parent, so HTTPS mixed-content/PNA fetch is unnecessary.
let tvBridge=false,bridgeParent='',bridgePending=new Map();
function bridgeSend(payload){
 return new Promise((resolve,reject)=>{
  if(!tvBridge||window.parent===window){reject(Error('Open the QR/link shown on your TV.'));return;}
  const id=Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);
  const timer=setTimeout(()=>{bridgePending.delete(id);reject(Error('TV did not respond. Open a new TV link.'));},10000);
  bridgePending.set(id,{resolve,reject,timer});window.parent.postMessage({brunio:'tv-client',action:'send',id,payload},bridgeParent);
 });
}
if(tvLaunch.get('bridge')==='1'&&window.parent!==window){
 try{
  bridgeParent=validCastAddress(tvLaunch.get('tv')||'');tvBridge=true;castEndpoint=bridgeParent;$('castAddress').value=bridgeParent;
  window.addEventListener('message',event=>{
   if(event.origin!==bridgeParent||event.source!==window.parent||event.data?.brunio!=='tv-bridge')return;
   const data=event.data;
   if(data.connected){castToken='local-parent-bridge';pollNowPlaying();castRender();toast(t('Conectado a tu TV.'));if(currentDetail&&$('detail').open)showDetail(currentDetail);}
   if(data.id&&bridgePending.has(data.id)){const pending=bridgePending.get(data.id);clearTimeout(pending.timer);bridgePending.delete(data.id);if(data.ok)pending.resolve({ok:true,status:data.status});else pending.reject(Error(data.error||'TV unavailable.'));}
  });
  window.parent.postMessage({brunio:'tv-client',action:'ready'},bridgeParent);
 }catch(e){tvBridge=false;toast(e.message);}
}

// Only local TV requests; no Supabase polling or stream URLs.
let nowPlayingBusy=false;
function clockLabel(ms){const s=Math.max(0,Math.floor(Number(ms||0)/1000));return Math.floor(s/60)+':'+String(s%60).padStart(2,'0');}
async function pollNowPlaying(){
 if(nowPlayingBusy||!session||!castToken||document.hidden){if(!castToken||!session)$('nowPlaying').hidden=true;return;}
 nowPlayingBusy=true;const connection=castToken;
 try{const data=await castPost('/status',{action:'status'},true);if(connection!==castToken||!session)return;const status=data.status||data,box=$('nowPlaying');box.hidden=false;box.replaceChildren(el('p',t('Reproduciendo ahora'),'eyebrow'));
  if(!status.active){box.append(el('p',t('Sin reproducción activa en TV.')));return;}
  const row=el('div',undefined,'now-row'),src=safeImage(status.poster);if(src){const img=el('img');img.src=src;img.alt='';row.append(img);}const info=el('div');info.append(el('h3',status.title||'BruniO'),el('p',(status.loading?t('Cargando en TV…'):status.playing?t('Reproduciendo'):t('Pausado'))+(status.season?' · S'+status.season+' E'+status.episode:'')+' · '+clockLabel(status.position)+' / '+clockLabel(status.duration)));
  if(/^tmdb:(movie|series):[1-9][0-9]*$/.test(status.cloud||'')){const b=el('button',t('Detalles de ')+(status.title||''),'quiet');b.onclick=()=>openDetail({cloudId:status.cloud,type:status.cloud.split(':')[1],id:Number(status.cloud.split(':')[2]),title:status.title,poster:status.poster});info.append(b);}row.append(info);box.append(row);
 }catch(e){if(connection===castToken){$('nowPlaying').hidden=false;$('nowPlaying').replaceChildren(el('p',e.message));}}
 finally{nowPlayingBusy=false;}
}
$('recents').onclick=()=>setView('recents');
setInterval(pollNowPlaying,5000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)pollNowPlaying();});
window.addEventListener('hashchange',()=>{const match=/^#([ms])([0-9a-z]{1,6})$/i.exec(location.hash);if(match){pendingShared='tmdb:'+(match[1].toLowerCase()==='m'?'movie':'series')+':'+parseInt(match[2],36);openSharedTitle();}});

// Download URLs/tickets live only in the open title dialog, never in share links/storage.
let downloadRevision=0,downloadMaxGb=5;
try{const cap=localStorage.getItem('brunio-download-max-gb');if(cap!==null&&Number.isFinite(Number(cap))&&Number(cap)>=0&&Number(cap)<=1000)downloadMaxGb=Number(cap);}catch{}
async function openDownloads(item,refresh=false){
 const maxGb=downloadMaxGb;const revision=++downloadRevision,profile=selected(),owner=session?.user.id,detail=detailRevision;
 let panel=$('downloadPanel');if(panel)panel.remove();panel=el('section',undefined,'download-panel');panel.id='downloadPanel';$('detailBody').append(panel);
 const valid=()=>revision===downloadRevision&&detail===detailRevision&&profile===selected()&&owner===session?.user.id&&$('detail').open;
 const title=el('h3',language==='en'?'Download · TorBox':'Descargar · TorBox'),status=el('p',t('Cargando…'));const reload=el('button',language==='en'?'Refresh sources':'Actualizar fuentes','quiet');reload.onclick=()=>openDownloads(item,true);const capLabel=el('label',language==='en'?'Maximum file size (GB) · 0 = unlimited':'Tamaño máximo (GB) · 0 = sin límite'),capInput=el('input');capInput.type='number';capInput.min='0';capInput.max='1000';capInput.step='any';capInput.required=true;capInput.value=String(maxGb);capLabel.append(capInput);
 const applyCap=el('button',language==='en'?'Apply limit':'Aplicar límite','quiet');applyCap.onclick=()=>{if(!capInput.reportValidity())return;const value=Number(capInput.value);if(!Number.isFinite(value)||value<0||value>1000)return;downloadMaxGb=value;try{localStorage.setItem('brunio-download-max-gb',String(value));}catch{}openDownloads(item);};
 const capControls=el('div',undefined,'download-cap');capControls.append(capLabel,applyCap,reload);panel.append(title,capControls,status);
 panel.scrollIntoView({behavior:'smooth',block:'nearest'});
 try{
  const result=await api('/functions/v1/brunio-downloads','POST',{action:'sources',maxGb,refresh,cloud:item.cloudId,profile,season:Number($('castSeason').value||1),episode:Number($('castEpisode').value||1),language});if(!valid())return;
  status.textContent=language==='en'?'Choose a source. With a limit enabled, unknown sizes are hidden. Files download directly from TorBox.':'Elige una fuente. Con un límite activo, se ocultan tamaños desconocidos. El archivo baja directamente desde TorBox.';
  if(!result.sources?.length){status.textContent=language==='en'?'No TorBox sources match this size limit. Change the limit or check your TV add-ons.':'No hay fuentes de TorBox con este límite. Cambia el límite o revisa tus add-ons en TV.';return;}
  for(const source of result.sources){
   const row=el('article',undefined,'download-source'),meta=el('div');meta.append(el('strong',source.name),el('p',source.filename),el('small',source.provider+(source.size>0?' · '+(source.size/1000000000).toFixed(2)+' GB':'')));
   const button=el('button',language==='en'?'Generate link':'Generar enlace','quiet');row.append(meta,button);panel.append(row);
   button.onclick=async()=>{
    button.disabled=true;const message=el('p',t('Cargando…'));row.append(message);
    try{
     const result=await api('/functions/v1/brunio-downloads','POST',{action:'link',maxGb,ticket:source.ticket,profile,language});if(!valid())return;
     const url=new URL(result.url);if(url.protocol!=='https:'||!url.hostname.endsWith('.torbox.app')||url.hostname==='api.torbox.app'||url.username||url.password)throw Error(language==='en'?'Invalid download link.':'Enlace de descarga inválido.');
     const link=el('a','↓ Download','primary download-link');link.href=url.href;link.download=result.filename||'';link.target='_blank';link.rel='noopener noreferrer';link.referrerPolicy='no-referrer';button.replaceWith(link);appendExternalPlayerActions(row,url.href);
     message.textContent=language==='en'?'Ready. Press Download. Your browser manages the file and save location.':'Listo. Pulsa Download. Tu navegador maneja el archivo y dónde guardarlo.';
    }catch(e){if(valid()){message.textContent=e.message;button.disabled=false;}}
   };
  }
 }catch(e){if(valid())status.textContent=e.message;}
}

function isAppleMobile(){return /iPad|iPhone|iPod/i.test(navigator.userAgent||'')||(/Mac/i.test(navigator.platform||'')&&Number(navigator.maxTouchPoints)>1);}
function vlcStreamLink(raw){const url=new URL(raw);if(url.protocol!=='https:'||!url.hostname.endsWith('.torbox.app')||url.hostname==='api.torbox.app'||url.username||url.password)throw Error('Invalid media URL');return 'vlc-x-callback://x-callback-url/stream?url='+encodeURIComponent(url.href);}
function appendExternalPlayerActions(row,raw){
 const actions=el('div',undefined,'external-player-actions');
 if(isAppleMobile()){
  const vlc=el('a',language==='en'?'▶ Open in VLC':'▶ Abrir en VLC','quiet external-player-link');vlc.href=vlcStreamLink(raw);vlc.target='_top';vlc.rel='noreferrer';actions.append(vlc);
 }
 const copy=el('button',language==='en'?'Copy link for another player':'Copiar enlace para otro player','quiet');copy.type='button';copy.onclick=async()=>{
  try{if(!navigator.clipboard)throw Error('Clipboard unavailable');await navigator.clipboard.writeText(raw);toast(t('Enlace copiado'));}
  catch{let field=actions.querySelector?.('input');if(!field){field=el('input');field.type='text';field.readOnly=true;field.value=raw;field.setAttribute('aria-label',language==='en'?'Media link for external player':'Enlace para reproductor externo');actions.append(field);}field.focus();field.select();}
 };actions.append(copy);
 actions.append(el('p',isAppleMobile()?(language==='en'?'Open in VLC streams from TorBox and requires VLC installed. For offline playback: Download → Files/Downloads → Share → VLC. The website cannot open a downloaded local file automatically.':'Abrir en VLC reproduce desde TorBox y requiere VLC instalado. Para verlo offline: Download → Archivos/Descargas → Compartir → VLC. La web no puede abrir automáticamente el archivo local descargado.'):(language==='en'?'Paste the link into your external player’s network stream option. For offline playback, open the downloaded file from your device.':'Pega el enlace en la opción de red de tu reproductor externo. Para verlo offline, abre el archivo descargado desde tu dispositivo.')));
 row.append(actions);
}
